import QtQuick
import Quickshell
import Quickshell.Io
import Quickshell.Wayland

// Display-only idle handling: DPMS off after `timeoutSeconds` without input,
// DPMS on at the next input. This plugin never suspends, hibernates, or locks;
// the only commands it runs are `omarchy-brightness-display off|on`.
Item {
  id: root

  // Injected by omarchy-shell.
  property var shell: null

  readonly property int timeoutSeconds: 600
  readonly property string stayAwakePath: Quickshell.env("HOME") + "/.local/state/omarchy/indicators/stay-awake"

  property bool stayAwake: false
  property bool screensOff: false

  function setScreens(on) {
    if (on === !root.screensOff) return
    root.screensOff = !on
    console.log("screen-sleep: displays " + (on ? "on" : "off"))
    Quickshell.execDetached(["omarchy-brightness-display", on ? "on" : "off"])
  }

  // Respects Wayland idle inhibitors (e.g. fullscreen video) and Omarchy's
  // Stay Awake toggle.
  IdleMonitor {
    id: idleMonitor
    enabled: !root.stayAwake
    timeout: root.timeoutSeconds
    respectInhibitors: true
    onIsIdleChanged: root.setScreens(!isIdle)
  }

  onStayAwakeChanged: if (stayAwake) setScreens(true)

  FileView {
    path: root.stayAwakePath
    watchChanges: true
    printErrors: false
    onLoaded: root.stayAwake = true
    onLoadFailed: root.stayAwake = false
    onFileChanged: reload()
  }

  // Polling fallback: FileView can't watch a file that doesn't exist yet.
  Process {
    id: stayAwakeProbe
    command: ["test", "-e", root.stayAwakePath]
    onExited: function(exitCode) { root.stayAwake = exitCode === 0 }
  }

  Timer {
    interval: 5000
    running: true
    repeat: true
    onTriggered: if (!stayAwakeProbe.running) stayAwakeProbe.running = true
  }

  // Never leave the screens dark if the plugin is reloaded or disabled.
  Component.onDestruction: if (root.screensOff) Quickshell.execDetached(["omarchy-brightness-display", "on"])

  IpcHandler {
    target: "screen-sleep"

    function status(): string {
      return JSON.stringify({
        timeout: root.timeoutSeconds,
        idle: idleMonitor.isIdle,
        screensOff: root.screensOff,
        stayAwake: root.stayAwake
      })
    }
  }
}
EOF
